#!/bin/bash\n\n# Render deployment setup script\n# This script helps you set up automatic deployments from GitHub to Render\n\nset -e\n\necho \"🚀 Render Deployment Setup\"\necho \"\"\necho \"This script will help you configure automatic deployments.\"\necho \"\"\n\necho \"📋 Follow these steps:\"\necho \"\"\necho \"1. Go to https://render.com/dashboard\"\necho \"2. Create a new Web Service and connect your GitHub repo\"\necho \"3. Configure the service with these settings:\"\necho \"   - Name: gaming-website\"\necho \"   - Environment: Docker\"\necho \"   - Region: Choose closest to you\"\necho \"   - Plan: Free (or Pro for 24/7)\"\necho \"\"\n\necho \"4. In Settings, copy the 'Deploy Hook' URL\"\necho \"\"\n\necho \"5. Go to your GitHub repo → Settings → Secrets and Variables → Actions\"\necho \"6. Create a new secret called 'RENDER_DEPLOY_HOOK'\"\necho \"7. Paste the deploy hook URL as the value\"\necho \"\"\n\necho \"8. Create .github/workflows/deploy.yml with this content:\"\necho \"\"\n\ncat << 'EOF'\nname: Deploy to Render\n\non:\n  push:\n    branches:\n      - main\n\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    \n    steps:\n      - uses: actions/checkout@v3\n      \n      - name: Set up Python\n        uses: actions/setup-python@v4\n        with:\n          python-version: '3.11'\n      \n      - name: Install dependencies\n        run: |\n          python -m pip install --upgrade pip\n          pip install -r requirements.txt\n      \n      - name: Run tests\n        run: |\n          pytest tests/ -v\n      \n      - name: Deploy to Render\n        env:\n          RENDER_DEPLOY_HOOK: ${{ secrets.RENDER_DEPLOY_HOOK }}\n        run: |\n          curl $RENDER_DEPLOY_HOOK\nEOF\n\necho \"\"\necho \"✅ Setup complete!\"\necho \"\"\necho \"Now, every time you push to main branch, GitHub Actions will:\"\necho \"1. Run your tests\"\necho \"2. Trigger automatic deployment on Render\"\necho \"\"\necho \"📚 Resources:\"\necho \"- Render Deploy Hooks: https://render.com/docs/deploy-hooks\"\necho \"- GitHub Actions: https://docs.github.com/actions\"\n"
